  static JSONObject copied(String kind,JSONObject input){String value=AuditDiagnosticExport.copy(kind,input);check("Bounded output for "+kind,value.getBytes(StandardCharsets.UTF_8).length<=AuditDiagnosticExport.MAX_BYTES);check("No arbitrary source text for "+kind,!value.contains(SECRET));return J.parse(value);}
