    value=fixture();value.getJSONObject("report").getJSONObject("signals").getJSONObject("apiChecks").getJSONObject("probes").getJSONObject("canvas").put("state","failed");check("Failed operation cannot carry hash",!mainProbe(copied("deep",value)).has("hash"));
    check("Unimplemented Worker audio does not acquire output hash",!deep.getJSONObject("contexts").getJSONObject("worker").getJSONObject("probes").getJSONObject("audio").has("hash"));
    value=fixture();JSONObject cycle=new JSONObject();cycle.put("self",cycle);value.put("unexpected",cycle);check("Unknown cyclic input is never serialized",copied("deep",value).getInt("schema")==1);
    value=fixture();JSONObject nested=new JSONObject();for(int i=0;i<1000;i++)nested=J.obj("nested",nested);value.put("unknownDeep",nested);check("Unknown deeply nested input is not traversed",copied("deep",value).getInt("schema")==1);
    value=fixture();for(int i=0;i<129;i++)value.put("unknown"+i,SECRET);check("Object field cap produces safe unavailable",copied("deep",value).getString("status").equals("unavailable"));
